const err = $input.item.json;

const workflowName = err.workflow?.name || '(알 수 없음)';
const nodeName = err.execution?.lastNodeExecuted || '(알 수 없음)';
const errorMsg = err.execution?.error?.message || '상세 메시지 없음';
const errorDesc = err.execution?.error?.description || '';
const execId = err.execution?.id || '';
const execUrl = err.execution?.url || '';
const ts = new Date().toISOString().replace('T',' ').substring(0,19);

const lines = [
  `🚨 **WBS Agent 오류 알림** (${ts})`,
  ``,
  `워크플로: **${workflowName}**`,
  `마지막 노드: ${nodeName}`,
  `오류: ${errorMsg}`,
];
if (errorDesc) lines.push(`상세: ${errorDesc}`);
if (execUrl) lines.push(`실행 로그: ${execUrl}`);
else if (execId) lines.push(`실행 ID: ${execId}`);

return [{ json: { text: lines.join('\n') } }];

